<?php
namespace App\Services;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
final class EnrollmentTransitions {
 public function __construct(public EnrollmentTransitionAccess $access,public EnrollmentTransitionPreview $preview){}
 public function setup(Request $r):array{[$sid,$scope]=$this->access->context($r);return ['today'=>$this->access->today(),'school'=>DB::table('schools')->where('id',$sid)->first(['name','code']),'can_manage'=>$this->access->can($r),'can_academics'=>$this->access->can($r,'academics.manage'),'sessions'=>DB::table('academic_sessions')->where('school_id',$sid)->orderByDesc('starts_on')->get(),'sections'=>DB::table('sections as s')->join('classes as c','c.id','=','s.class_id')->join('academic_sessions as y','y.id','=','s.academic_session_id')->join('campuses as p','p.id','=','s.campus_id')->where('s.school_id',$sid)->whereIn('s.campus_id',$scope)->orderByDesc('y.starts_on')->orderBy('c.position')->orderBy('s.name')->get(['s.*','c.name as class_name','c.position as class_position','y.name as session_name','y.starts_on as session_start','y.ends_on as session_end','y.status as session_status','p.name as campus_name','p.status as campus_status'])];}
 private function items(Request $r,int $sid,object $source,array $items):array{$clean=[];foreach($items as $i){$en=$this->access->row('enrollments',$sid,$i['source_enrollment_id']);abort_unless($en->section_id===$source->id,404);if(!empty($i['target_section_id']))$this->access->section($r,$i['target_section_id']);$hold=$i['decision']==='hold';$clean[]=['source_enrollment_id'=>(int)$i['source_enrollment_id'],'decision'=>$i['decision'],'target_section_id'=>$hold||empty($i['target_section_id'])?null:(int)$i['target_section_id'],'roll_no'=>$hold||trim($i['roll_no']??'')===''?null:trim($i['roll_no']),'reason'=>trim($i['reason']??'')===''?null:trim($i['reason'])];}usort($clean,fn($a,$b)=>$a['source_enrollment_id']<=>$b['source_enrollment_id']);return $clean;}
 public function save(Request $r,array $d,?int $id=null):array{return DB::transaction(function()use($r,$d,$id){$sid=$this->access->lock($r);$b=$id?$this->access->batch($r,$id):null;if($b&&($b->status!=='draft'||$b->lock_version!=$d['lock_version']))$this->access->fail('Draft changed or was finalized. Reload before saving.');$source=$this->access->section($r,$b?->source_section_id??$d['source_section_id']);$kind=$b?->kind??$d['kind'];$session=$this->access->row('academic_sessions',$sid,$d['target_session_id']);if($kind==='transfer'&&$session->id!==$source->academic_session_id)$this->access->fail('Transfer plans stay within their source session.');$items=$this->items($r,$sid,$source,$d['items']);$v=['title'=>$d['title'],'target_session_id'=>$session->id,'effective_on'=>$d['effective_on'],'reason'=>$d['reason']];if(!$b){$hash=hash('sha256',json_encode($v+['kind'=>$kind,'source_section_id'=>$source->id,'items'=>$items]));$old=DB::table('enrollment_transition_batches')->where('school_id',$sid)->where('entry_key',$d['entry_key'])->first();if($old){$this->access->batch($r,$old->id);if($old->request_hash!==$hash)$this->access->fail('This plan key was already used for different details.');return ['id'=>$old->id,'message'=>'Transition draft already saved.'];}$id=DB::table('enrollment_transition_batches')->insertGetId($v+['school_id'=>$sid,'source_section_id'=>$source->id,'kind'=>$kind,'status'=>'draft','created_by'=>$this->access->access->membership($r)->id,'entry_key'=>$d['entry_key'],'request_hash'=>$hash,'created_at'=>now(),'updated_at'=>now()]);}else DB::table('enrollment_transition_batches')->where('school_id',$sid)->where('id',$id)->update($v+['lock_version'=>$b->lock_version+1,'updated_at'=>now()]);DB::table('enrollment_transition_items')->where('school_id',$sid)->where('batch_id',$id)->whereNotIn('source_enrollment_id',array_column($items,'source_enrollment_id'))->delete();foreach($items as $i)DB::table('enrollment_transition_items')->updateOrInsert(['school_id'=>$sid,'batch_id'=>$id,'source_enrollment_id'=>$i['source_enrollment_id']],$i+['updated_at'=>now()]);$this->access->audit($r,$b?'draft_updated':'draft_created','enrollment_transition_batches',$id,['items'=>count($items),'effective_on'=>$d['effective_on'],'reason'=>$d['reason']]);return ['id'=>$id,'message'=>'Transition draft saved. Enrollment has not changed.'];});}
 public function detail(Request $r,int $id):array{[$sid]=$this->access->context($r);$b=$this->access->batch($r,$id);$b->snapshot=$b->snapshot?json_decode($b->snapshot,true):null;return ['batch'=>$b,'source'=>$this->access->section($r,$b->source_section_id),'items'=>DB::table('enrollment_transition_items as i')->join('enrollments as e','e.id','=','i.source_enrollment_id')->join('students as p','p.id','=','e.student_id')->where('i.school_id',$sid)->where('i.batch_id',$id)->orderBy('i.source_enrollment_id')->get(['i.*','e.student_id','p.admission_no','p.first_name','p.last_name']),'can_manage'=>$this->access->can($r)];}
 public function listing(Request $r,array $d){[$sid,$scope]=$this->access->context($r);$q=DB::table('enrollment_transition_batches as b')->join('sections as s','s.id','=','b.source_section_id')->where('b.school_id',$sid)->whereIn('s.campus_id',$scope)->whereNotExists(fn($q)=>$q->selectRaw('1')->from('enrollment_transition_items as i')->join('sections as t','t.id','=','i.target_section_id')->whereColumn('i.batch_id','b.id')->whereNotIn('t.campus_id',$scope));if(!empty($d['status']))$q->where('b.status',$d['status']);return $q->orderByDesc('b.id')->paginate(20,['b.id','b.title','b.kind','b.effective_on','b.status','b.lock_version','b.applied_at']);}
 public function cancel(Request $r,int $id,array $d):array{return DB::transaction(function()use($r,$id,$d){$sid=$this->access->lock($r);$b=$this->access->batch($r,$id);if($b->status!=='draft'||$b->lock_version!=$d['lock_version'])$this->access->fail('Only the current draft can be cancelled.');DB::table('enrollment_transition_batches')->where('school_id',$sid)->where('id',$id)->update(['status'=>'cancelled','lock_version'=>$b->lock_version+1,'updated_at'=>now()]);$this->access->audit($r,'draft_cancelled','enrollment_transition_batches',$id,['reason'=>$d['reason']]);return ['message'=>'Draft cancelled. Enrollment history was not changed.'];});}
 public function apply(Request $r,int $id,array $d):array{return DB::transaction(function()use($r,$id,$d){$sid=$this->access->lock($r);$b=$this->access->batch($r,$id);if($b->status==='applied'){if($b->confirmed_digest!==$d['source_digest'])$this->access->fail('This batch was already applied with different confirmation details.');return ['id'=>$id,'message'=>'This transition batch was already applied.'];}if($b->status!=='draft'||$b->lock_version!=$d['lock_version'])$this->access->fail('Draft changed or was cancelled. Reload before confirmation.');$p=$this->preview->calculate($r,$id);if(!$p['can_apply'])$this->access->fail('Resolve the preview exceptions or place those students on hold. No enrollment was changed.');if($p['source_digest']!==$d['source_digest'])$this->access->fail('Roster, dates, decisions or destination capacity changed. Calculate a fresh preview.');$mid=$this->access->access->membership($r)->id;$events=[];foreach($p['rows'] as &$row){if($row['decision']==='hold')continue;$before=$row['before'];$status=match($row['decision']){'graduate'=>'graduated','withdraw'=>'withdrawn',default=>'completed'};$after=['status'=>$status,'ends_on'=>$row['closes_on']];DB::table('enrollments')->where('school_id',$sid)->where('id',$row['source_enrollment_id'])->update($after+['updated_at'=>now()]);$target=null;if($row['target_section_id'])$target=DB::table('enrollments')->insertGetId(['school_id'=>$sid,'student_id'=>$row['student_id'],'section_id'=>$row['target_section_id'],'roll_no'=>$row['roll_no'],'starts_on'=>$row['starts_on'],'ends_on'=>$row['ends_on'],'status'=>'active','created_at'=>now(),'updated_at'=>now()]);DB::table('students')->where('school_id',$sid)->where('id',$row['student_id'])->update(['status'=>match($row['decision']){'graduate'=>'graduated','withdraw'=>'withdrawn',default=>'active'},'updated_at'=>now()]);$state=['source'=>$after,'target_enrollment_id'=>$target,'student_status'=>in_array($row['decision'],['graduate','withdraw'],true)?$status:'active'];$event=DB::table('enrollment_transition_events')->insertGetId(['school_id'=>$sid,'batch_id'=>$id,'item_id'=>$row['item_id'],'source_enrollment_id'=>$row['source_enrollment_id'],'target_enrollment_id'=>$target,'decision'=>$row['decision'],'applied_by'=>$mid,'applied_at'=>now(),'before_state'=>json_encode($before),'after_state'=>json_encode($state),'created_at'=>now(),'updated_at'=>now()]);$row['target_enrollment_id']=$target;$row['event_id']=$event;$row['after']=$state;$events[]=$event;}unset($row);$p['applied_by_name']=$r->user()->name;$p['applied_at']=now()->toDateTimeString();DB::table('enrollment_transition_batches')->where('school_id',$sid)->where('id',$id)->update(['status'=>'applied','lock_version'=>$b->lock_version+1,'applied_by'=>$mid,'applied_at'=>now(),'confirmed_digest'=>$d['source_digest'],'snapshot'=>json_encode($p),'updated_at'=>now()]);$this->access->audit($r,'batch_applied','enrollment_transition_batches',$id,['counts'=>$p['counts'],'effective_on'=>$b->effective_on,'reason'=>$b->reason,'event_ids'=>$events]);return ['id'=>$id,'message'=>'Transition batch applied. Previous records were retained.'];});}
}
